    25→func TestChunkJSONL_LargeContent(t *testing.T) {
    26→	// Create a transcript larger than MaxChunkSize
    27→	var lines []string
    28→	lineContent := `{"type":"human","message":"` + strings.Repeat("x", 1000) + `"}`
    29→	// Calculate how many lines needed to exceed MaxChunkSize
    30→	linesNeeded := (MaxChunkSize / len(lineContent)) + 100 // Extra to ensure multiple chunks
    31→
    32→	for range linesNeeded {
    33→		lines = append(lines, lineContent)
    34→	}
    35→	content := []byte(strings.Join(lines, "\n"))
    36→
    37→	chunks, err := ChunkJSONL(content, MaxChunkSize)
    38→	if err != nil {
    39→		t.Fatalf("ChunkJSONL error: %v", err)
    40→	}
    41→	if len(chunks) < 2 {
    42→		t.Errorf("Expected at least 2 chunks for large content, got %d", len(chunks))
    43→	}
    44→
    45→	// Verify each chunk is under MaxChunkSize
    46→	for i, chunk := range chunks {
    47→		if len(chunk) > MaxChunkSize {
    48→			t.Errorf("Chunk %d exceeds MaxChunkSize: %d > %d", i, len(chunk), MaxChunkSize)
    49→		}
    50→	}
    51→
    52→	// Verify reassembly
    53→	reassembled := ReassembleJSONL(chunks)
    54→	if string(reassembled) != string(content) {
    55→		t.Errorf("Reassembled content doesn't match original")
    56→	}
    57→}
