func TestChunkTranscript_SingleOversizedMessage(t *testing.T) {
	ag := &GeminiCLIAgent{}

	// Create a single message that exceeds maxSize
	largeContent := strings.Repeat("x", 1000)
	transcript := GeminiTranscript{
		Messages: []GeminiMessage{
